import{_ as t}from"./chunks/d7934098438af5ce408b.Dba7sCv-.js";import{_ as o,o as a,c as i,a5 as r}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"The Path Of The NPC (How To Not End Up Mediocre)","description":"","frontmatter":{"title":"The Path Of The NPC (How To Not End Up Mediocre)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-path-of-the-npc-how-to-not-end-up-mediocre.md","filePath":"en/letters/the-path-of-the-npc-how-to-not-end-up-mediocre.md"}'),n={name:"en/letters/the-path-of-the-npc-how-to-not-end-up-mediocre.md"};function s(h,e,p,l,c,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="the-path-of-the-npc-how-to-not-end-up-mediocre" tabindex="-1">The Path Of The NPC (How To Not End Up Mediocre) <a class="header-anchor" href="#the-path-of-the-npc-how-to-not-end-up-mediocre" aria-label="Permalink to &quot;The Path Of The NPC (How To Not End Up Mediocre)&quot;">​</a></h1><p>Dan Koe · 2023-04-29 · <a href="https://thedankoe.com/letters/the-path-of-the-npc-how-to-not-end-up-mediocre/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-path-of-the-npc-how-to-not-end-up-mediocre">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/r1LI1-K08II?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>You have been copying people since you were born.</p><p>That’s how you learn to operate in society.</p><p>There are 2 paths this can lead to:</p><h3 id="_1-the-path-of-the-npc" tabindex="-1">1) The path of the NPC <a class="header-anchor" href="#_1-the-path-of-the-npc" aria-label="Permalink to &quot;1) The path of the NPC&quot;">​</a></h3><p>The NPC, or non-player character, is an individual that is a slave to their programming.</p><p>They never question their beliefs (you know, the ones that were projected on them and they accepted without a fight).</p><p>They never seek to change.</p><p>The default path of going to school, getting a job, and retiring at 65 are the only big goals they have.</p><p>They never branch into the unknown.</p><p>Their life becomes boring, mechanical, and animalistic. They never discover new potentials for their life. And even if they do, it scares them back into their comfortable hole.</p><h3 id="_2-the-path-of-the-main-character" tabindex="-1">2) The path of the Main Character <a class="header-anchor" href="#_2-the-path-of-the-main-character" aria-label="Permalink to &quot;2) The path of the Main Character&quot;">​</a></h3><p>A main character is an individual with a clear vision for the future, self-generated goals to actualize it, and non-negotiable actions they must take on a daily basis.</p><p>They are aware that the conventional career path leads to the same mediocre lifestyle that you can observe in 99% of the population.</p><p>They understand that they must take responsibility for their lives.</p><p>They understand that they are entitled to nothing. That they must create success whether the odds are for or against them.</p><p><strong>Reminder</strong>: As you know, Solopreneur Sprints (build the base of your one-person business) starts on the 15th. <a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">Enroll here</a>.</p><h2 id="you-are-a-perspective-vessel-in-a-subjective-reality" tabindex="-1">You Are A Perspective Vessel In A Subjective Reality <a class="header-anchor" href="#you-are-a-perspective-vessel-in-a-subjective-reality" aria-label="Permalink to &quot;You Are A Perspective Vessel In A Subjective Reality&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>Reality is perspective, and you are a perspective vessel.</p><p>The NPC and Main Character move through reality in the way they do because of their perspective.</p><p>Your perspective is forged with time through conditioning.</p><p>Conditioning = the information you process with your mind repeated over time until those thought processes are automatic.</p><p>Perspective and identity are closely tied.</p><p>Joe Dispenza has a saying:</p><p>“Your personality creates your personal reality.”</p><p>Your identity (your sense of who you are) influences three major things:</p><ul><li>Your perspective or worldview</li><li>How you perceive situations from that perspective</li><li>The choices you make because of both</li></ul><p>The NPC perspective is closed-minded and narrowed on the societal goals projected onto them.</p><p>The NPC is identified with the beliefs, ideas, and thoughts that they register in their awareness.</p><p>Because of their ‘average Joe’ identity, they will feel pulled to do things that align with that.</p><p>They will:</p><ul><li>Make similar friends</li><li>Change their external appearance (to fit in)</li><li>Consume movies, media, and information that reinforces that identity</li></ul><p>All of which narrow their mind on certain problems and potentials for their life.</p><p>For the NPC, the problems often involve paying the bills, advancing their career in a corporate power ladder, and saving a few bucks here and there for retirement.</p><p>Most of the information they consume will be negative, polarizing, and attention-grabbing keeping them in chains.</p><p>The most dangerous threat to society is someone who isn’t reliant on it.</p><p>From that conditioned perspective, the NPC will interpret situations and opportunities in that way.</p><p>When someone shows them a business opportunity, like starting a personal brand, their mind will flood with the excuses and defense mechanisms programmed into it by their parents, school, and news outlets.</p><p>When someone encourages them to work on their health, they attack it with whatever narrative the news has given them to defend themselves.</p><p>It is your job to become aware of your mental programming.</p><p>That is how you become the main character of your story.</p><p>You must realize and work to change the identity that you were conditioned to have in a society that glorifies mediocrity.</p><p>Changing who you are is difficult, and nobody can do it for you.</p><p>It takes intention and effort.</p><h2 id="the-intelligent-imitation-process-become-the-main-character" tabindex="-1">The Intelligent Imitation Process (Become The Main Character) <a class="header-anchor" href="#the-intelligent-imitation-process-become-the-main-character" aria-label="Permalink to &quot;The Intelligent Imitation Process (Become The Main Character)&quot;">​</a></h2><p>To begin conditioning your mind for success you must:</p><ul><li>Set new goals for a higher quality of life</li><li>Immerse yourself in the information that will condition a new perspective</li><li>Make progress and notice the positive outcome it has on your life.</li></ul><p>Start with what matters most:</p><p>Your mind body, spirit, and finances.</p><p>Somebody who values fitness, like a bodybuilder, will make choices that lead to a higher quality of life.</p><p>It’s baked into the identity</p><p>They will eat healthy food, train, and avoid situations that are detrimental to their progress.</p><p>The same holds true for someone who values building a business, spreading good, and a mind that is witty and wise.</p><p>The choices they make lead to more energy, less financial stress, and a deeper satisfaction from intellectual development.</p><p>Most people will think that they should try to stop copying, imitating, or being conditioned by information.</p><p>That’s impossible.</p><p>Imitation is how you learn.</p><p>The difference between the NPC and Main Character is that the latter imitates with an intelligent or conscious mind.</p><p>They are <em>aware</em> of what they are imitating and how it impacts their life.</p><p>The NPC will imitate the herd and go down the same path.</p><p>The main character will imitate who they deem successful in alignment with the future they want to create.</p><h3 id="step-1-create-a-perspective-you-can-grow-into" tabindex="-1">Step 1) Create a perspective you can grow into. <a class="header-anchor" href="#step-1-create-a-perspective-you-can-grow-into" aria-label="Permalink to &quot;Step 1) Create a perspective you can grow into.&quot;">​</a></h3><p>Perspective is reality.</p><p>If you want to create your own reality, you have to create a new perspective.</p><p>The perspective you create will give you a lens to view your present situations through.</p><p>You “grow into” that perspective through conscious practice.</p><p>Answer these questions:</p><ul><li>What does my ideal day look like?</li><li>What do I want to do as my life’s work?</li><li>How do I want to impact people’s lives?</li><li>What do I want to look and feel like?</li><li>What values and habits will I have to adopt to bring those to life?</li></ul><p>From there, practice putting on the perspective of your future self as you go about your days.</p><p>It will be difficult at first, but you will start to spot problems and opportunities that you can act on.</p><h3 id="step-2-choose-3-5-mentors-that-you-aspire-to-be-like" tabindex="-1">Step 2) Choose 3-5 “mentors” that you aspire to be like. <a class="header-anchor" href="#step-2-choose-3-5-mentors-that-you-aspire-to-be-like" aria-label="Permalink to &quot;Step 2) Choose 3-5 “mentors” that you aspire to be like.&quot;">​</a></h3><p><em>You become what you consume, so consume</em> <em>in accordance with</em> <em>who you want to become.</em></p><p>Make this process easy by writing down the 3-5 names of the people that have changed <em>your</em> perspective.</p><p>What is your favorite book that you recommend to everyone? Write down the author’s name.</p><p>Who is the YouTuber, podcaster, or blogger that you can’t stop watching? The one that “blows your mind” every time they post?</p><p>What social media accounts do you follow that make you think, “How did they say that so perfectly?”</p><p>Because that’s the thing… not everyone thinks that. Only you. The combination and <em>connection</em> of these “mentors” is how you create your own niche, perspective, and content that separates you from the crowd.</p><p>Re-read the first chapter of your favorite books again — I guarantee your brain will light up.</p><h3 id="step-3-become-a-mad-scientist" tabindex="-1">Step 3) Become a mad scientist. <a class="header-anchor" href="#step-3-become-a-mad-scientist" aria-label="Permalink to &quot;Step 3) Become a mad scientist.&quot;">​</a></h3><p>The good life is a series of experiments.</p><p>You can’t copy it from someone else. You have to try, fail, and collect the pieces that make your individual life great.</p><p>The NPC takes what is put in front of them.</p><p>The main character leans into the trial and error that reflects in nature toward evolution and growth.</p><p>As you are immersing yourself in information from your mentors and pushing toward your goals, follow the scientific process.</p><ul><li><strong>Research</strong> – don’t mindlessly consume content. Gather it to apply to your goals.</li><li><strong>Test</strong> – don’t take advice or information as law. Test if it works for your situation.</li><li><strong>Experiment</strong> – don’t be dogmatic about one method. Try different diets, business models, and religious ideologies until the truth of each blurs in the middle.</li><li><strong>Discover</strong> – note patterns that get results in alignment with your goals.</li><li><strong>Document</strong> – write down what gets you results. This is the valuable information that you can sell or leverage.</li></ul><p>When you treat your life as a project, it becomes profitable.</p><p>A personal brand is just discovering yourself in public and getting paid for the research you do.</p><h3 id="step-4-create-or-be-created" tabindex="-1">Step 4) Create or be created. <a class="header-anchor" href="#step-4-create-or-be-created" aria-label="Permalink to &quot;Step 4) Create or be created.&quot;">​</a></h3><p>The primary difference between the NPC and the Main Character is creation.</p><p>The NPC is created through years of conditioning that remains unconscious.</p><p>The Main Character is created through years of conscious conditioning (they choose their inputs).</p><p>Nobody escapes conditioning.</p><p>It’s happening all around you.</p><p>This letter is conditioning you. Hopefully toward something good.</p><p>The modern world is create or be created.</p><p>The choice is yours (at every millisecond of the day).</p><p>Enjoy your weekend.</p><p>– Dan</p><p>P.S. Solopreneur Sprints starts on May 15th.</p><p>If you want to build the base of your one-person business with my brand and high-performing content systems, <a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">check it out here</a>.</p><p>The price of Digital Economics will also double on that date. You can find it on the same page.</p>',104)])])}const f=o(n,[["render",s]]);export{y as __pageData,f as default};
